const items = [
  {type: 'fruit', name: 'apple'},
  {type: 'veggie', name: 'carrot'},
  {type: 'fruit', name: 'banana'}
];
const grouped = items.reduce((acc, item) => {
  acc[item.type] = acc[item.type] || [];
  acc[item.type].push(item.name);
  return acc;
}, {});
console.log(grouped);
